-- Original reporting view retained for application compatibility.
CREATE OR REPLACE VIEW view_top_designers AS
SELECT u.id, u.full_name, u.username,
       COUNT(DISTINCT s.id) AS total_karya,
       COUNT(DISTINCT l.user_id) AS total_likes
FROM users u
LEFT JOIN shots s ON u.id = s.user_id
LEFT JOIN likes l ON s.id = l.shot_id
WHERE u.role = 'user'
GROUP BY u.id, u.full_name, u.username;